import{_ as t,o as e,c as d,Q as a}from"./chunks/framework.48927342.js";const u=JSON.parse('{"title":"Psychologist Job Application","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/emails/12-psychologist-job-application.md","filePath":"en/more/maltese/practice/emails/12-psychologist-job-application.md"}'),o={name:"en/more/maltese/practice/emails/12-psychologist-job-application.md"},r=a('<h1 id="psychologist-job-application" tabindex="-1">Psychologist Job Application <a class="header-anchor" href="#psychologist-job-application" aria-label="Permalink to &quot;Psychologist Job Application&quot;">​</a></h1><p><strong>Scenario:</strong> The applicant writes to the counselling clinic to apply for the position of psychologist.</p><h2 id="email-header" tabindex="-1">Email Header <a class="header-anchor" href="#email-header" aria-label="Permalink to &quot;Email Header&quot;">​</a></h2><p><strong>Lil (To):</strong> <a href="mailto:info@clinika.com" target="_blank" rel="noreferrer">info@clinika.com</a><strong>Mingħand (From):</strong> [isem]@email.com <strong>Data (Date):</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett (Subject):</strong> Applikazzjoni ta&#39; xogħol ta&#39; psikologu</p><h2 id="full-email" tabindex="-1">Full Email <a class="header-anchor" href="#full-email" aria-label="Permalink to &quot;Full Email&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:info@clinika.com" target="_blank" rel="noreferrer">info@clinika.com</a><strong>Mingħand:</strong> [isem]@email.com <strong>Data:</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Applikazzjoni ta&#39; xogħol ta&#39; psikologu</p><p>Għażiż Sinjur / Sinjura,</p><p>Qed nikteb biex napplika għall-impjieg ta&#39; psikologu.</p><p>Għandi lawrja fil-psikoloġija u esperjenza ta&#39; erba&#39; snin.</p><p>Jiena nisma&#39; lin-nies bil-paċenzja u bil-qalb.</p><p>Ngħin lill-klijenti biex jifhmu s-sentimenti tagħhom.</p><p>Nirrispetta l-privatezza ta&#39; kull persuna.</p><p>Nista&#39; naħdem ma&#39; tfal u adulti.</p><p>Noffri appoġġ b&#39;mod professjonali u ħanin.</p><p>Nixtieq noffri l-għajnuna tiegħi lit-tim tagħkom.</p><p>Grazzi talli qiesu l-applikazzjoni tiegħi.</p><p>Nispera li nisma&#39; mingħandkom dalwaqt.</p><p>Tislijiet, [Ismek]</p></blockquote><h2 id="sentence-by-sentence-translation-and-word-notes" tabindex="-1">Sentence-by-Sentence Translation and Word Notes <a class="header-anchor" href="#sentence-by-sentence-translation-and-word-notes" aria-label="Permalink to &quot;Sentence-by-Sentence Translation and Word Notes&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:info@clinika.com" target="_blank" rel="noreferrer">info@clinika.com</a></p><p><strong>Translation:</strong> To: <a href="mailto:info@clinika.com" target="_blank" rel="noreferrer">info@clinika.com</a></p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Lil</td><td>to; recipient</td><td>Maltese label for the email &quot;To&quot; field</td></tr><tr><td><a href="mailto:info@clinika.com" target="_blank" rel="noreferrer">info@clinika.com</a></td><td>email address</td><td>The clinic&#39;s recruitment email (example)</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: [isem]@email.com</p><p><strong>Translation:</strong> From: [your name]@email.com</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Mingħand</td><td>from; sender</td><td>Maltese label for the email &quot;From&quot; field; literally &quot;from ...&quot;</td></tr><tr><td>[isem]@email.com</td><td>email address</td><td>Placeholder for your email; replace with your real one</td></tr></tbody></table><p><strong>Malti:</strong> Data: 15 ta&#39; Ottubru 2026</p><p><strong>Translation:</strong> Date: 15 October 2026</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Data</td><td>date</td><td>Email &quot;Date&quot; field; Maltese date format is &quot;day ta&#39; month year&quot;</td></tr><tr><td>15</td><td>fifteen</td><td>Day in the date</td></tr><tr><td>ta&#39;</td><td>of</td><td>Links the day and the month</td></tr><tr><td>Ottubru</td><td>October</td><td>Month name</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Applikazzjoni ta&#39; xogħol ta&#39; psikologu</p><p><strong>Translation:</strong> Subject: Application for the Position of Psychologist</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Suġġett</td><td>subject</td><td>Email &quot;Subject&quot; field</td></tr><tr><td>Applikazzjoni</td><td>application</td><td>Feminine loanword from application</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>xogħol</td><td>work; job</td><td>Masculine noun</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>psikologu</td><td>psychologist</td><td>Masculine loanword from psychologist</td></tr></tbody></table><p><strong>Malti:</strong> Għażiż Sinjur / Sinjura,</p><p><strong>Translation:</strong> Dear Sir / Madam,</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għażiż</td><td>dear</td><td>Masculine singular form</td></tr><tr><td>Sinjur</td><td>sir; Mr.</td><td>Masculine noun</td></tr><tr><td>/</td><td>or</td><td>Indicates a choice between two</td></tr><tr><td>Sinjura</td><td>madam; Mrs.</td><td>Feminine noun</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Qed nikteb biex napplika għall-impjieg ta&#39; psikologu.</p><p><strong>Translation:</strong> I am writing to apply for the position of psychologist.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Qed</td><td>am (progressive marker)</td><td>Used with a verb to indicate an ongoing action</td></tr><tr><td>nikteb</td><td>I write</td><td>First-person singular present</td></tr><tr><td>biex</td><td>in order to</td><td>Introduces a purpose clause</td></tr><tr><td>napplika</td><td>I apply</td><td>First-person singular form, loanword from apply</td></tr><tr><td>għall-impjieg</td><td>for the job</td><td>Contracted <code>għal</code> + <code>l-impjieg</code></td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>psikologu</td><td>psychologist</td><td>Masculine loanword from psychologist</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Għandi lawrja fil-psikoloġija u esperjenza ta&#39; erba&#39; snin.</p><p><strong>Translation:</strong> I have a psychology degree and four years of experience.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għandi</td><td>I have</td><td>First-person singular form of <code>għand</code></td></tr><tr><td>lawrja</td><td>degree</td><td>Feminine loanword from laurea</td></tr><tr><td>fil-psikoloġija</td><td>in psychology</td><td>Contracted <code>f&#39;</code> + <code>il-psikoloġija</code></td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>esperjenza</td><td>experience</td><td>Feminine noun</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>erba&#39;</td><td>four</td><td>Numeral</td></tr><tr><td>snin</td><td>years</td><td>Plural of <code>sena</code></td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Jiena nisma&#39; lin-nies bil-paċenzja u bil-qalb.</p><p><strong>Translation:</strong> I listen to people patiently and wholeheartedly.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Jiena</td><td>I</td><td>First-person singular pronoun (variant of <code>Jien</code>)</td></tr><tr><td>nisma&#39;</td><td>I listen; I hear</td><td>First-person singular form</td></tr><tr><td>lin-nies</td><td>to people</td><td>Contracted <code>li</code> + <code>in-nies</code></td></tr><tr><td>bil-paċenzja</td><td>patiently</td><td>Contracted <code>b&#39;</code> + <code>il-paċenzja</code></td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>bil-qalb</td><td>wholeheartedly; sincerely</td><td>Contracted <code>b&#39;</code> + <code>il-qalb</code> &quot;heart&quot;</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Ngħin lill-klijenti biex jifhmu s-sentimenti tagħhom.</p><p><strong>Translation:</strong> I help clients understand their feelings.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Ngħin</td><td>I help</td><td>First-person singular form</td></tr><tr><td>lill-klijenti</td><td>to the clients</td><td>Contracted <code>li</code> + <code>il-klijenti</code></td></tr><tr><td>biex</td><td>in order to</td><td>Introduces a purpose clause</td></tr><tr><td>jifhmu</td><td>they understand</td><td>Third-person plural form</td></tr><tr><td>s-sentimenti</td><td>the feelings</td><td>Plural of <code>sentiment</code>, with the definite article</td></tr><tr><td>tagħhom</td><td>their</td><td>Plural possessive pronoun</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Nirrispetta l-privatezza ta&#39; kull persuna.</p><p><strong>Translation:</strong> I respect the privacy of every person.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nirrispetta</td><td>I respect</td><td>First-person singular form, loanword from respect</td></tr><tr><td>l-privatezza</td><td>the privacy</td><td>Feminine noun with the definite article</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>kull</td><td>every; each</td><td>Determiner</td></tr><tr><td>persuna</td><td>person</td><td>Feminine noun</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Nista&#39; naħdem ma&#39; tfal u adulti.</p><p><strong>Translation:</strong> I can work with children and adults.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nista&#39;</td><td>I can</td><td>First-person singular form</td></tr><tr><td>naħdem</td><td>I work</td><td>First-person singular present</td></tr><tr><td>ma&#39;</td><td>with</td><td>Preposition</td></tr><tr><td>tfal</td><td>children</td><td>Plural of <code>tifel/tifla</code></td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>adulti</td><td>adults</td><td>Plural of <code>adult</code>, loanword from adult</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Noffri appoġġ b&#39;mod professjonali u ħanin.</p><p><strong>Translation:</strong> I offer support in a professional and compassionate way.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Noffri</td><td>I offer</td><td>First-person singular form</td></tr><tr><td>appoġġ</td><td>support</td><td>Masculine noun</td></tr><tr><td>b&#39;mod</td><td>in a ... way</td><td><code>b&#39;</code> + <code>mod</code> &quot;manner&quot;</td></tr><tr><td>professjonali</td><td>professional</td><td>Adjective loanword from professional</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>ħanin</td><td>compassionate; gentle</td><td>Adjective</td></tr></tbody></table><h3 id="_8" tabindex="-1">8. <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;8.&quot;">​</a></h3><p><strong>Malti:</strong> Nixtieq noffri l-għajnuna tiegħi lit-tim tagħkom.</p><p><strong>Translation:</strong> I would like to offer my help to your team.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nixtieq</td><td>I would like; I wish</td><td>Polite expression of a wish</td></tr><tr><td>noffri</td><td>I offer</td><td>First-person singular form</td></tr><tr><td>l-għajnuna</td><td>the help</td><td>Feminine noun with the definite article</td></tr><tr><td>tiegħi</td><td>my; mine</td><td>Possessive pronoun</td></tr><tr><td>lit-tim</td><td>to the team</td><td>Contracted <code>li</code> + <code>it-tim</code></td></tr><tr><td>tagħkom</td><td>your (plural)</td><td>Plural possessive pronoun</td></tr></tbody></table><h3 id="_9" tabindex="-1">9. <a class="header-anchor" href="#_9" aria-label="Permalink to &quot;9.&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi talli qiesu l-applikazzjoni tiegħi.</p><p><strong>Translation:</strong> Thank you for considering my application.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Grazzi</td><td>thank you</td><td>Polite phrase</td></tr><tr><td>talli</td><td>for (your) ...</td><td>Written expression introducing a reason</td></tr><tr><td>qiesu</td><td>they considered</td><td>Third-person plural past of <code>qies</code></td></tr><tr><td>l-applikazzjoni</td><td>the application</td><td>Feminine noun with the definite article</td></tr><tr><td>tiegħi</td><td>my; mine</td><td>Possessive pronoun</td></tr></tbody></table><h3 id="_10" tabindex="-1">10. <a class="header-anchor" href="#_10" aria-label="Permalink to &quot;10.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li nisma&#39; mingħandkom dalwaqt.</p><p><strong>Translation:</strong> I hope to hear from you soon.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nispera</td><td>I hope</td><td>First-person singular form</td></tr><tr><td>li</td><td>that; introduces a clause</td><td>Conjunction</td></tr><tr><td>nisma&#39;</td><td>I hear; receive news</td><td>First-person singular form</td></tr><tr><td>mingħandkom</td><td>from you (plural)</td><td><code>mingħand</code> + <code>-kom</code> &quot;you&quot;</td></tr><tr><td>dalwaqt</td><td>soon</td><td>Adverb</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, [Ismek]</p><p><strong>Translation:</strong> Regards, [your name] (formal email closing).</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Tislijiet</td><td>regards; best wishes</td><td>Formal email/letter closing, literally &quot;greetings/regards&quot;</td></tr><tr><td>Ismek</td><td>your name</td><td><code>isem</code> &quot;name&quot; + <code>-ek</code> &quot;your&quot;; replace with your real name</td></tr></tbody></table>',65),i=[r];function n(l,s,h,p,c,g){return e(),d("div",null,i)}const b=t(o,[["render",n]]);export{u as __pageData,b as default};
